import sys,json,hashlib,urllib.request,urllib.parse,zipfile,io
from pathlib import Path,PurePosixPath
from concurrent.futures import ThreadPoolExecutor
p=json.load(sys.stdin)
root=Path(p['root']);root.mkdir(parents=True,exist_ok=True)
def save(path,raw):
 path.parent.mkdir(parents=True,exist_ok=True)
 if path.exists():
  assert path.read_bytes()==raw,('existing artifact mismatch',str(path))
 else:
  with path.open('xb') as f:f.write(raw)
for group,meta in p['metadata'].items():
 for name,raw in meta.items():save(root/group/name,raw.encode())
def download(a):
 path=root/a['group']/a['file_name']
 if path.exists():raw=path.read_bytes()
 else:
  host=urllib.parse.urlparse(a['url']).hostname
  assert host and host.endswith('.oaiusercontent.com')
  raw=urllib.request.urlopen(a['url'],timeout=60).read()
 assert len(raw)==a['bytes'] and hashlib.sha256(raw).hexdigest()==a['sha256']
 with zipfile.ZipFile(io.BytesIO(raw)) as z:
  assert z.testzip() is None
  for m in z.infolist():
   name=PurePosixPath(m.filename);assert not name.is_absolute() and '..' not in name.parts
  members=sum(not m.is_dir() for m in z.infolist())
 save(path,raw)
 return {k:v for k,v in a.items() if k!='url'}|{'members':members}
with ThreadPoolExecutor(max_workers=6) as ex:rows=list(ex.map(download,p['artifacts']))
report={'schema':'heptatorch.pr31-official-artifact-custody.v1','status':'ORIGINAL_ARTIFACTS_PRESERVED','source_head':'cef47b8fc36e4afefad4b4c4e53625f8f62e0a57','original_metadata_bytes_preserved':True,'archives':rows,'native_executed':False,'Torch_executed':False,'hosted_admission_not_inferred':True}
save(root/'custody.json',(json.dumps(report,indent=2)+'\n').encode())
